scenarios.example_code:
import { putFlag } from '@projexlight/sdk-feature-flags';
await putFlag({
  tenant_id, name: 'new-portfolio-dashboard',
  default_value: false,
  targeting_rules: [
    { match: { cohort: 'beta' }, value: true },
  ],
});

import { evaluate } from '@projexlight/sdk-feature-flags';
const { value, reason } = await evaluate({
  flag: 'new-portfolio-dashboard',
  persona: { id, cohort: 'beta', tenant_id },
});
if (value) renderNewDashboard(); else renderOldDashboard();

import { advanceRollout } from '@projexlight/sdk-feature-flags';
await advanceRollout({
  flag_id, to_percentage: 50,
  advanced_by_persona_id, reason: 'beta-metrics-look-good',
});

import { killSwitch } from '@projexlight/sdk-feature-flags';
await killSwitch({
  flag_id, pulled_by_persona_id, reason: 'P1-incident-2026-05-26',
});

subscribeEvents('tenant.offboarded.v1', async (e) => {
  await deleteFlagsForTenant({ tenant_id: e.payload.tenant_id });
});
